// @generated by:gauntlet run:godseye-e08-independent-gauntlet

import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { ObservabilityEngine } from "../packages/core/src/observability.js";
import {
  attemptIntent,
  type E08UsageFixture,
  e08UsageFixture,
  unknownOutcome,
} from "./helpers/e08-usage.js";
import { required } from "./helpers/e08-values.js";

describe("E08 actual journal correlations and scoped accounting queries", () => {
  let f: E08UsageFixture;
  beforeEach(async () => {
    f = await e08UsageFixture();
  });
  afterEach(async () => {
    await f.finish();
    await f.store.close();
  });
  it("T-AC-811 joins the actual admitted Agent task to its Foundation run and real overview counts", async () => {
    const engine = new ObservabilityEngine(f.store, {
      now: f.clock.now,
      usageSummary: () => f.usage.summarySystem(),
    });
    const timeline = await engine.timeline(f.freshOwner(), {
      projectId: f.project.id,
      environmentId: f.development.id,
    });
    expect(timeline.entries).toContainEqual(
      expect.objectContaining({
        id: f.task.id,
        kind: "agent",
        correlation: { kind: "execution", id: f.task.runId },
        source: "control-journal",
      }),
    );
    expect(timeline.entries).toContainEqual(
      expect.objectContaining({ id: f.task.runId, kind: "execution", state: "active" }),
    );
    expect(await engine.overview(f.freshOwner())).toMatchObject({
      projectCount: 2,
      activeRuns: 1,
      usage: { reservedMicros: 10000 },
    });
    expect(
      (await engine.timeline(f.freshOwner(), { projectId: f.secondProject.id })).entries,
    ).toHaveLength(0);
  });
  it("T-AC-808 cannot attach another project's actual execution to a bound source", async () => {
    const engine = new ObservabilityEngine(f.store, { now: f.clock.now });
    const environment = required(
      f.secondProject.environments.find((row) => row.kind === "development"),
    );
    const source = await engine.registerSource(
      f.freshOwner(),
      {
        name: "other-project",
        authenticatedActorId: "other-service",
        kind: "service",
        staleAfterSeconds: 60,
        scope: { projectId: f.secondProject.id, environmentId: environment.id, resourceId: null },
      },
      randomUUID(),
    );
    await expect(
      engine.ingest(
        { id: "other-service", kind: "service", projectIds: [f.secondProject.id] },
        source.id,
        {
          observedAt: f.clock.now().toISOString(),
          state: "healthy",
          event: "heartbeat",
          level: "info",
          code: "CROSS_SCOPE",
          correlation: { kind: "execution", id: required(f.task.runId) },
          metrics: [],
        },
        randomUUID(),
      ),
    ).rejects.toThrow();
    expect((await engine.logs(f.freshOwner(), {})).records).toHaveLength(0);
  });
  it("T-AC-801 filters aggregate evidence on the server and rejects mismatched ancestry", async () => {
    await f.record();
    const scoped = await f.usage.overview(f.freshOwner(), {
      projectId: f.project.id,
      environmentId: f.development.id,
      profileId: f.profile.id,
      runId: required(f.task.runId),
    });
    expect(scoped.attempts).toHaveLength(1);
    expect(scoped.summary.attemptCount).toBe(1);
    expect(
      (await f.usage.overview(f.freshOwner(), { projectId: f.secondProject.id })).attempts,
    ).toHaveLength(0);
    await expect(
      f.usage.overview(f.freshOwner(), {
        projectId: f.secondProject.id,
        environmentId: f.development.id,
      }),
    ).rejects.toThrow();
  });
  it("T-AC-809 paginates one immutable snapshot without reusing its cursor under a different scope", async () => {
    await f.start();
    await f.reporter.intent(attemptIntent);
    await f.reporter.intent({
      ...attemptIntent,
      sequence: 2,
      parentSequence: 1,
      relation: "continuation",
      requestHash: "b".repeat(64),
    });
    const first = await f.usage.overview(f.freshOwner(), { projectId: f.project.id, limit: 1 });
    expect(first.page.total).toBe(2);
    expect(first.truncated).toBe(true);
    expect(first.page.nextCursor).toBeTruthy();
    const second = await f.usage.overview(f.freshOwner(), {
      projectId: f.project.id,
      limit: 1,
      cursor: required(first.page.nextCursor),
    });
    expect(second.attempts).toHaveLength(1);
    expect(required(second.attempts[0]).id).not.toBe(required(first.attempts[0]).id);
    expect(second.page.snapshotAt).toBe(first.page.snapshotAt);
    await expect(
      f.usage.overview(f.freshOwner(), {
        projectId: f.secondProject.id,
        limit: 1,
        cursor: required(first.page.nextCursor),
      }),
    ).rejects.toThrow();
  });
  it("T-AC-803 cannot attach a price published after the actual attempt intent", async () => {
    await f.reporter.intent(attemptIntent);
    await f.putPrice();
    await f.reporter.outcome({
      ...unknownOutcome,
      state: "succeeded",
      categories: { input: 1, output: 0, cacheRead: 0, cacheWrite: 0, reasoning: 0 },
    });
    expect((await f.usage.overview(f.freshOwner())).attempts[0]).toMatchObject({
      priceId: null,
      estimatedMicros: null,
    });
  });
  it("T-AC-803 never estimates a final bill from incomplete physical stream evidence", async () => {
    await f.putPrice();
    const row = await f.record({
      ...unknownOutcome,
      state: "unknown",
      categories: { input: 10, output: 2, cacheRead: 0, cacheWrite: 0, reasoning: 0 },
    });
    expect(row).toMatchObject({
      estimatedMicros: null,
      outcome: { categories: { input: 10, output: 2 } },
    });
  });
});
